MOD = 10**9 + 7

def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n - 1)

def calculate_subsequence_sum(n, pre_sum):
    memo = [0] * (max(n + 1, 6) - 1)
    memo[0] = 1
    cache = {}

    def sum_subsequence(i):
        ans = 0
        while i >= 0:
            ans = (ans + memo[i] * pre_sum) % MOD
            # Move to previous tuple in memo
            i -= 1
        return ans

    def exp_mod(base, k):
        power = 1
        while k > 0:
            # Increment power by 1 whenever k is odd
            if k % 2:
                power = (power * base) % MOD
            base = (base * base) % MOD
            k /= 2
        return power

    for i in range(n + 1):
        pre_sum = sum_subsequence(i)
        if memo[1 + i] == 0:
            memo[1 + i] = sum_subsequence(n - i)
            cache[(n, i)] = exp_mod(memo[1 + i], i)

    return [cache[(n_i, i_i)] for n_i, i_i in cache.keys()]

T = int(input())
for _ in range(T):
    n = int(input())
    result = sum([abs(num) for num in calculate_subsequence_sum(n - 1, 0)])
