def calculate_probability(n, m, gifts):
    gift_counts = defaultdict(int)
    max_price_gifts = defaultdict(int)

    for i in range(m):
        count, *prices = gifts[i]
        gift_counts[i] = count
        max_price_gifts[i] = sorted(prices, reverse=True)

    total_gifts = sum(count for count in gift_counts.values())
    valid_gifts = sum(count for count in gift_counts.values()) - n

    if total_gifts == valid_gifts:
        return 1.0

    def can_get_max_n_gifts(n_gifts, gift_counts, gift_max_prices):
        # Recursively count the number of valid gift combinations
        @lru_cache(None)
        def dfs(min_gifts, max_gifts):
            if not max_gifts or min_gifts > max_gifts:
                return 0
            if min_gifts < n_gifts and min_gifts > max_gifts:
                return dfs(min_gifts + 1, max_gifts - gift_counts[gift_max_prices[min_gifts - 1]] - 1)
            return max(gift_counts[gift] * fn(gift) for gift, fn in gift_max_prices[:min_gifts]) + dfs(min_gifts + 1, max_gifts)

        return dfs(0, valid_gifts)

    return can_get_max_n_gifts(n, gift_counts, max_price_gifts) / (max_price_gifts[0] + 1) ** n

