import sys
from collections import defaultdict

def build_opt_list(blacklist, whitelist):
    subnet_counts = defaultdict(int)
    subnet_counts.update(color_to_subnet_count(blacklist))
    subnet_counts.update(color_to_subnet_count(whitelist))

    optimised_list = []
    colour_count = (1 << 32) - 1
    current_subnet = colour_count
    prev_colour = -1

    for colour in sorted(subnet_counts.iterkeys()):
        if colour_count ^ (colour_count & colour) == prev_colour and current_subnet < colour_count:
            optimised_list.append(subnet_to_ip(str(current_subnet)))
            current_subnet += colour_counts[colour]
            colour_counts[colour] = 0
        else:
            current_subnet -= colour_counts[colour]

        prev_colour = colour_count ^ (colour_count & colour)

    return len(optimised_list)

def subnet_to_ip(subnet_str):
    components = tuple(map(int, subnet_str.split('.')))
    prefix_length = 0 if '/' not in subnet_str else int(subnet_str[4:])
    parts = []
    for offset in range(32, 0, -prefix_length):
        bits = bin((1 << offset) & ~((1 << 32) - 1))[2:].zfill(34)
        for octet, color in zip(components[:-1], bits):
            if color == '1':
                parts.append(f'{octet}/{offset}')
    return '/'.join(parts)

def color_to_subnet_count(colors):
    subnet_count = 0
    for components in colors.values():
        for offset in range(32, 0, -3):
            subnet_count += (1 << offset) & ~((1 << 32) - 1)
    return subnet_count

def solve(subnets):
    blacklist, whitelist = subnets
    optimised_blacklist = {}
    for subtype in blacklist:
        optimised_blacklist[color_to_subnet_count(set(subtype))]
    for subtype in whitelist:
        optimised_blacklist[color_to_subnet_count(set(subtype)) ^ 1]

    return build_opt_list(list(optimised_blacklist), list(subnet => int(ipv4) for subtype, ipv4 in whitelist))

input_file = sys.stdin.read
subnets = tuple(tuple(map(int, input().strip()))) for _ in range(int(input_file().split()[0].strip())))

print(solve(subnets))
