            if not last_parent or next_time < next_n.time_for_next_visit(last_parent):
                graph[node].remove((next_n, next_time))
                queue.append((next_n.time_for_next_visit(node), next_time + next_time))
                visited.add(next_n)
                parent[next_n] = last_parent
                if next_n not in graph[last_parent] and prev_from_here != start:
                    graph[next_n].append((prev_from_here, arrive_time))
                    queue.append((next_n.time_for_next_visit(last_parent), arrive_time))

    current_node = arrive_time
    result = []
    while node != start:
        prev_search_outline = visited.pop()
        prev_search_outline = current_node

