def calculate_min_cost_and_optimal_vertices(n: int, prices: List[int], edges: List[List[int]]) -> None:
    from collections import defaultdict

    # Build the graph
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    def dfs(node: int, parent: int, depth: int, times: int) -> bool:
        parentnode = node
        while graph[node]:
            deepest = True
            for child in graph[node]:
                childrenTimes = dfs(child, node, depth + 1, 0)
                if childrenTimes:
                    parentnode = child
                    deepest = False
            if deepest:
                return True | (graph[node][-1] > depth)
            else:
                graph[node].pop()
        return depth >= depth + times and not parentnode

    res = 0
    optimal_vertices_count = 0
    ret = []

    for vertex in range(1, n + 1):
        node_to_time = 0
        for child in graph[vertex]:
            if child in graph[vertex]:
                while graph[child]:
                    deepest = True
                    for child in graph[child]:
                        childrenTimes = dfs(child, child, 1, 0)
                        if childrenTimes:
                            node_to_time = max(node_to_time, childrenTimes)
                node_to_time += children[node]
                if node_to_time == vertex:
                    res = res + vertex - node_to_time
                    graph[vertex].remove(vertex)
                    graph[vertex].remove(child)
