from collections import defaultdict

def min_transport_time(n, m, cannons):
    times = [[-1] * n for _ in range(n)]
    connections = defaultdict(set)

    for a, b, c in cannons:
        times[a][b] = 1 + (times[b][a] := c // n) % 2 ** 28
        connections[a].add((b, -c + 1))
        connections[int((b + 1) % n)].add((a, -c + 1))

    def search(start, end):
        D, visited = [[float('inf')] * n for _ in range(n)], [False] * n
        D[start][end], visited[start] = 0, True
        Q = [start]
        while Q:
            temp = []
            for i in Q:
                for to, t in connections[i]:
                    k = -times[to][i] // 2 ** 28
                    if D[start][k] + t < D[i][to]:
                        D[start][k], D[i][to], temp = D[i][to], D[start][k], (k,)
            Q = temp

        return all(val == D[start][i] for i in range(len(D[start])))

    for i in range(n):
        for res in range(n):
            if times[i][res] == -1 and times[res][i] == -1:
                if search(i, res):
                    for z in range(n):
                        for k in range(256):
                            if sum(times[i][z] & (2 ** z) << ((a - 1) * 256) == times[res][z] for a in range(n)) & (2 ** (i - 1) << (n * 256 - 1)) == (2 ** (res - 1) << (n * 256 - 1)):
                                times[i][z] = times[i][res] = min(times[i][z], times[res][z] + k + 1)

    return times
