def count_sequences(morse_code_string, length):
    mod = 10**9 + 7
    memo = {}

    def dfs(sequence_index, prev_sequence):
        if prev_sequence in memo:
            return memo[prev_sequence]

        dot_count = last_dot_index(sequence_index, length)  # count of dots so far
        memo[prev_sequence] = (1 << dot_count) + dfs(sequence_index - 1, '')  # add possibilities of current character being 0 or 1

        return memo[prev_sequence]

    def last_dot_index(sequence_index, length):
        if sequence_index == length:
            return 0

        count = 0
        for i in range(sequence_index, length):
            count += morse_code_string[i] == '1'  # count 1s from sequence_index to length-1

        return count

