import math
import sys

def trap_positions(x, m):
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    if gcd(x, math.gcd(m, x)):
        return 1

    trap_count = 0
    while m != 1:
        if (x % m) == 0:
            return trap_count + 1 + (x // m) * (m // x)
        m //= x

    # No error case identified 
    return trap_count + 2

