import sys

def smallest_edges(n, edges):
    # Create adjacency list representation of the tree
    adj_list = [[] for _ in range(n)]
    for u, v, wt in edges:
        adj_list[u-1].append((v-1, wt))
        adj_list[v-1].append((u-1, wt))

    # Function to compute the minimum weight of edges delete to make the degree of a vertex d
    def degree_d(vertices, d):
        ntaken = [False] * n
        edges_taken = []
        result = 0
        for v in vertices:
            total = 0 
            for w, wt in adj_list[v]:
                if total + wt > d:
                    break
                total += wt
            else:
                for w, wt in adj_list[v]:
                    if not ntaken[w]:
                        break
                else:
                    result += total
                    ntaken[v] = True
                    for w, _ in adj_list[v]:
                        if ntaken[w]:
                            continue
                        edges_taken.append(w)
        return result

    total = 0
    for u, v, _ in edges:
        total += math.ceil(degree_d([u, v], n-1) / 2)

    return degree_d(range(n), 0)

