def build_graph(n, edges):
    graph = defaultdict(list)
    for a, b in edges:
        graph[a-1].append(b-1)
        graph[b-1].append(a-1)
    return graph

def bfs(graph, start):
    visited = {start}
    queue = deque([start])
    parent = defaultdict(int)
    while queue:
        current = queue.popleft()
        for neighbor in graph[current]:
            if neighbor not in visited:
                visited.add(neighbor)
                parent[neighbor] = current
                queue.append(neighbor)
    return parent

def dfs(graph, parent, cost, total_cost, start):
    subtree_cost = cost
    for neighbor in graph[start]:
        if neighbor not in parent:
            subtree_cost += dfs(graph, parent, cost + total_cost, total_cost, neighbor)
    return subtree_cost

def min_cost_to_target_total_cost(graph, n, ans, start, cost, s, target):
    parent = bfs(graph, start)
    res = set()
    indices = set()
    for vertex in range(n):
        if vertex not in parent:
            subtree_total_cost = dfs(graph, parent, cost, 0, vertex)
            if target <= subtree_total_cost + cost:
                res.add(vertex)
                indices.add(vertex)
    d = len(indices)
    if res:
        s += d*cost
        if ans[0] > (d*cost):
            ans[0] = (d*cost)
            ans[1] = indices
    return s

