def get_possible_states(N, M, S):
    dp = {tuple(S): 1}  # Start state with the initial string
    for _ in range(1, M + 1):
        dp_new = {}
        for state in dp:
            for i in range(len(state)):
                new_state = tuple(state[:i] + [0] + state[i + 1:])  # Substring from l_i to r_i is potential one
                dp_new.setdefault(new_state, 0)
                dp_new[new_state] += dp[state]  # Transition from the current state to the new state
            for i in range(len(state)):
                new_state = tuple(state[:i] + [1] + state[i + 1:])  # Substring from l_i to r_i is potential one
                dp_new.setdefault(new_state, 0)
                dp_new[new_state] += dp[state]  # Transition from the current state to the new state
        dp = dp_new
    return (sum(dp.values()) - len(dp)) % (10**9 + 7)

